// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.brainimport timber.log.Timberimport com.roshan.persona.brain.intent.classifier.EmbedderInterfaceimport com.roshan.persona.brain.intent.slots.NerEntityimport com.roshan.persona.brain.intent.slots.NerModelInterfaceimport com.roshan.persona.brain.intent.slots.NerTypeimport com.roshan.persona.vision.core.ConfidenceThresholdsimport com.roshan.persona.vision.core.OmniSlmEntityTypeimport com.roshan.persona.vision.core.OmniSlmRuntimeimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Omni-SLM Brain Bridge (Module 6 v4 — Step 6.1, Brain Upgrade). * * Wires the Omni-SLM unified runtime into the Brain's [EmbedderInterface] + * [NerModelInterface], **replacing** the v2 `TfIdfEmbedder` (hash-based, * semantic-useless) and the `null NER` (regex fallback only). * * ## Why this matters (per strategy v3 §"Module 6 → Brain Upgrade Impact") * * Before Module 6: *  - IntentClassifier's EmbeddingIntentMatcher uses `TfIdfEmbedder` — *    "switch on the torch" doesn't match "torch on" (zero semantic similarity). *  - SlotFiller's `NerModelInterface` is null — "call mom" doesn't extract *    `contact=mom` reliably; falls back to brittle regex. * * After Module 6 (this file): *  - EmbedderInterface is implemented by [OmniSlmEmbedder] → real 384-dim *    semantic embeddings via the unified Omni-SLM. 95%+ intent match accuracy. *  - NerModelInterface is implemented by [OmniSlmNerModel] → real PERSON / ORG / *    LOCATION / MISC extraction + Indian formats (PAN, Aadhaar, GSTIN, IFSC, UPI). * * ## How Brain wires this * * Brain's Hilt module (`BuiltInSkillsModule` in :feature:brain) currently * binds `TfIdfEmbedder` as [EmbedderInterface] and provides null for * [NerModelInterface]. * * Module 6's `VisionModule` (Step 6.8) will OVERRIDE those bindings via * Hilt `@Binds` (replacing the brain's defaults). Until then, this file * defines the implementations + unit tests verify correctness — Brain will * consume them at Step 6.8 integration. * * ## Privacy * *  - Embeddings + NER run 100% on-device via the Omni-SLM. *  - No text is uploaded to any server. *  - The Omni-SLM is INT4/INT2 quantized (per device capability). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Module 6 → Brain Upgrade Impact</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. OMNI-SLM EMBEDDER (replaces TfIdfEmbedder)// ═══════════════════════════════════════════════════════════════════════════/** * Brain's [EmbedderInterface] implemented via the unified Omni-SLM. * * Replaces `TfIdfEmbedder` (hash-based, semantic-useless) with real 384-dim * sentence embeddings. * * ## Performance (per strategy v4) * *  - Qualcomm QNN backend: 350-450 ms per inference *  - MediaTek NeuroPilot: 450-650 ms per inference *  - XNNPACK CPU fallback: 800-1200 ms per inference *  - All within Brain's [BrainSkill.DEFAULT_TIMEOUT_MS] = 5000 ms budget. * * ## Fallback * * If the Omni-SLM is disabled (ultra-low RAM tier) or fails to load, this * embedder returns a [Result.Failure]. The Brain's IntentClassifier then * falls back to `TfIdfEmbedder` (kept as cold-start fallback per v3 §"Hybrid * v3 Stack"). */@Singletonclass OmniSlmEmbedder @Inject constructor(    private val runtimeProvider: OmniSlmRuntimeProvider,) : EmbedderInterface {    override suspend fun embed(text: String): Result<FloatArray> {        Timber.tag(TAG).d("Embedding text via Omni-SLM: ${text.take(50)}...")        val runtime = runtimeProvider.get()        if (runtime.isDisabled) {            Timber.tag(TAG).w("Omni-SLM disabled — embed returning failure (Brain falls back to TfIdfEmbedder).")            return Result.failure(IllegalStateException("Omni-SLM disabled on this device"))        }        val tiered = runtime.embed(text)        val embedding = tiered.value        return if (tiered.isUsable && embedding != null) {            Timber.tag(TAG).d("Embed succeeded (confidence=${tiered.confidence}, tier=${tiered.tier}).")            Result.success(embedding)        } else {            Timber.tag(TAG).w("Embed rejected (confidence=${tiered.confidence}, tier=${tiered.tier}).")            Result.failure(RuntimeException("Omni-SLM embed rejected (confidence=${tiered.confidence})"))        }    }    private companion object {        private const val TAG = "OmniSlmEmbedder"    }}// ═══════════════════════════════════════════════════════════════════════════// 2. OMNI-SLM NER MODEL (replaces null NER + BERT-tiny)// ═══════════════════════════════════════════════════════════════════════════/** * Brain's [NerModelInterface] implemented via the unified Omni-SLM. * * Replaces the null NER (which forced SlotFiller to use regex fallback) with * real PERSON / ORG / LOCATION / MISC extraction + Indian formats * (PAN, Aadhaar, GSTIN, IFSC, UPI — see [OmniSlmEntityType]). * * ## Confidence-based extraction (per strategy v4 §"Issue 1: Confidence Thresholds") * *  - Confidence ≥ 0.60 → extract entity *  - Confidence < 0.60 → skip (Brain falls back to RegexPostProcessor) * * ## Hindi-English Code-Switching * * The Omni-SLM handles "Rahul ko call karo" (Hindi+English) correctly — * extracts `PERSON=Rahul` even though the sentence is mixed (the actual * norm in India, not pure Hindi or pure English). * * ## Entity Type Mapping * * The Omni-SLM returns extended types ([OmniSlmEntityType]) including Indian * formats. This bridge maps them down to Brain's [NerType] (4 types): * * | OmniSlmEntityType | NerType | * |-------------------|---------| * | PERSON | PERSON | * | ORGANIZATION | ORGANIZATION | * | LOCATION | LOCATION | * | DATE, TIME, MONEY, PHONE, EMAIL, URL, MEDICINE, DOSAGE, INDIAN_* | MISC | * | MISC | MISC | * * The extended type info is preserved in [NerEntity.text] (e.g., the original * phone number "+919876543210") — the Brain's SlotFiller can pattern-match * against it. */@Singletonclass OmniSlmNerModel @Inject constructor(    private val runtimeProvider: OmniSlmRuntimeProvider,) : NerModelInterface {    override suspend fun extract(text: String): Result<List<NerEntity>> {        Timber.tag(TAG).d("Extracting NER from text via Omni-SLM: ${text.take(50)}...")        val runtime = runtimeProvider.get()        if (runtime.isDisabled) {            Timber.tag(TAG).w("Omni-SLM disabled — NER returning empty (Brain falls back to regex).")            return Result.success(emptyList())        }        val tiered = runtime.extractEntities(text)        val allEntities = tiered.value ?: emptyList()        // Filter by confidence threshold (v4 §"Issue 1").        val extractedEntities = allEntities            .filter { ConfidenceThresholds.shouldExtractNerEntity(it.confidence) }            .map { omniEntity ->                NerEntity(                    text = omniEntity.text,                    type = omniEntity.type.toNerType(),                    confidence = omniEntity.confidence,                    startIndex = omniEntity.startIndex,                    endIndex = omniEntity.endIndex,                )            }        Timber.tag(TAG).d("NER extracted ${extractedEntities.size}/${allEntities.size} entities " +            "(confidence threshold=${ConfidenceThresholds.NER_EXTRACT}).")        return Result.success(extractedEntities)    }    /**     * Map [OmniSlmEntityType] → Brain's [NerType].     *     * Extended types (Indian formats, medicine, etc.) collapse to MISC —     * the original text preserves the value for SlotFiller pattern matching.     */    private fun OmniSlmEntityType.toNerType(): NerType = when (this) {        OmniSlmEntityType.PERSON -> NerType.PERSON        OmniSlmEntityType.ORGANIZATION -> NerType.ORGANIZATION        OmniSlmEntityType.LOCATION -> NerType.LOCATION        // All extended types collapse to MISC.        OmniSlmEntityType.DATE,        OmniSlmEntityType.TIME,        OmniSlmEntityType.MONEY,        OmniSlmEntityType.PHONE_NUMBER,        OmniSlmEntityType.EMAIL,        OmniSlmEntityType.URL,        OmniSlmEntityType.MEDICINE,        OmniSlmEntityType.DOSAGE,        OmniSlmEntityType.INDIAN_PAN,        OmniSlmEntityType.INDIAN_AADHAAR,        OmniSlmEntityType.INDIAN_GSTIN,        OmniSlmEntityType.INDIAN_IFSC,        OmniSlmEntityType.INDIAN_UPI_ID,        OmniSlmEntityType.MISC -> NerType.MISC    }    private companion object {        private const val TAG = "OmniSlmNerModel"    }}// ═══════════════════════════════════════════════════════════════════════════// 3. RUNTIME PROVIDER — abstracts ModelManager for Brain bridge// ═══════════════════════════════════════════════════════════════════════════/** * Provides the [OmniSlmRuntime] to the Brain bridge. * * Indirection needed because: *  - [OmniSlmEmbedder] + [OmniSlmNerModel] are `@Singleton`-scoped in *    :feature:vision (so the Brain can inject them). *  - But [OmniSlmRuntime] is created lazily by [com.roshan.persona.vision.core.ModelManager] *    (which loads the model on first use, evicts on camera minimize). *  - This provider breaks the circular dependency. * * Production: `VisionModule` provides an impl that delegates to `ModelManager.getOmniSlmRuntime()`. * Tests: Inject a fake that returns a `FakeOmniSlmDelegate`-backed runtime. */fun interface OmniSlmRuntimeProvider {    /** Get the current Omni-SLM runtime (may load lazily). */    suspend fun get(): OmniSlmRuntime}